<template>
  <div id="app" class="flex flex-col flex-grow p-4 md:p-6 max-w-7xl mx-auto w-full min-h-screen bg-transparent">
    <div v-if="screen === 'start'" class="screen-start flex flex-col items-center justify-center h-[900px] gap-6 bg-black/50 p-8 rounded-lg">
      <input 
        v-model="player.name" 
        placeholder="輸入名字" 
        class="px-4 py-2 rounded-lg border-2 border-yellow-400 focus:outline-none focus:ring-2 focus:ring-yellow-300 bg-gray-800 text-white placeholder-gray-400 text-lg w-64 text-center"
      />
      <button 
        @click="startGame" 
        class="px-6 py-2 bg-yellow-600 hover:bg-yellow-700 text-white font-bold rounded-lg shadow-md transition duration-200"
      >
        開始遊戲
      </button>
    </div>

    <div class="fixed inset-0 z-50 flex flex-col items-center justify-center bg-gray-900 p-6 md:hidden text-center">
      
      <div class="bg-gray-800 border border-gray-700 rounded-2xl p-8 shadow-2xl max-w-sm w-full">
        
        <div class="text-6xl mb-6 animate-bounce">
          📱
        </div>

        <h3 class="text-xl font-bold text-white mb-3">
          請切換至大螢幕
        </h3>

        <p class="text-gray-400 text-sm leading-relaxed mb-6">
          為了呈現最精緻的卡牌細節與特效，<br>
          目前版本僅支援 <strong>平板</strong> 或 <strong>電腦</strong> 遊玩。
        </p>

        <div class="w-16 h-1 bg-blue-500 rounded-full mx-auto opacity-50"></div>
      </div>

    </div>

    <!-- 選職業介面 -->
    <ChooseJob 
      v-if="screen === 'choose-job'"
      :player="player"
      @select-job="selectJob"
      @initcard="initCard"
    />

     <!-- 大廳介面 -->
    <GameLobby
      v-if="screen === 'lobby'"
      :player="player"
      :selectJob="player.job"
      :card="cards"
      @start-adventure="startExpedition"
      @backpack="openBag"
      @shop="openShop"
    />

    <!-- 戰鬥介面 -->
    <div v-if="screen === 'battle'" class="screen-game flex flex-col flex-grow relative">

      <!-- 飄字顯示 -->
      <div class="pointer-events-none absolute inset-0 z-50 overflow-hidden">
        <div
          v-for="ef in effects"
          :key="ef.id"
          class="absolute text-4xl font-black drop-shadow-md animate-float-up"
          :class="getEffectClass(ef.type)"
          :style="{ left: ef.x + '%', top: ef.y + '%'}"
        >
        {{ ef.type === 'damage' ? '-' : ['heal', 'armor'].includes(ef.type) ? '+' : '' }} {{ ef.value }}
        </div>
      </div>

      <!-- 頂部控制區 -->
      <header class="flex justify-between items-center p-2 mb-4 bg-gray-800 rounded-lg shadow-lg">
        <button @click="togglePause" class="px-4 py-2 bg-yellow-600 hover:bg-yellow-700 text-white font-bold rounded-lg transition duration-150 shadow-md">
          暫停
        </button>
        <div id="turn-indicator" class="text-xl font-bold p-2 rounded-lg bg-gray-700">
          回合 <span>{{ turn }}</span> - <span>{{ isPlayerTurn ? '玩家回合' : '敵人回合' }}</span>
        </div>
        <div class="w-20"></div>
      </header>

      <!-- 主戰場區 -->
      <main class="flex flex-col md:flex-row gap-6 mb-4 h-64">

        <!-- 玩家狀態區 (左側) -->
        <PlayerStats 
        :player="player"
        :is-hit="isPlayerHit" 
        :is-heal="isPlayerHeal"
        :is-armor="isPlayerArmor"
        @reset-hit="isPlayerHit = false"
        @reset-heal="isPlayerHeal = false"
        @reset-armor="isPlayerArmor = false"
        />

        <!-- 戰場中心區 -->
        <div class="w-full md:w-1/3 flex items-center justify-around relative overflow-hidden">
          <div class="character-box">
            <img 
              :src="displayImage"
              class="character-img"
              :class="{ 'animate-hit': isPlayerHit }"
            >
          </div>
        </div>

        <!-- 敵人狀態區 (右側) -->
        <EnemyStats 
        :enemy="currentEnemy" 
        :is-hit="isEnemyHit"
        :is-heal="isEnemyHeal"
        :is-armor="isEnemyArmor"
        @reset-hit="isEnemyHit = false"
        @reset-heal="isEnemyHeal = false"
        @reset-armor="isEnemyArmor = false"
        />
        <div v-if="gameMessage" class="game-message">
          {{ gameMessage }}
        </div>
      </main>

      <!-- 戰鬥日志區 -->
      <GameLog :logs="gameLog"/>

      <!-- 底部卡牌區 -->
      <PlayerHand 
        :hand="player.hand" 
        @playCard="clickCard" 
        @endTurn="endTurn" 
        :deckCount="deckCount" 
        :discardCount="discardCount"
      />

      <!-- 獎勵生成區 -->
      <RewardSelector
      :rewards="generatedRewards"
      :showRewards="showRewardBox"
      @selected="applyReward"
      @close="hideRewards"
      />

      <!-- 暫停視窗 -->
      <div
        class="fixed inset-0 bg-black/60 flex justify-center items-center z-50 transition duration-300"
        :class="showPause ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'"
      >
        <div class="bg-gray-900/90 text-white w-80 p-6 rounded-xl shadow-xl space-y-4">

          <h2 class="text-center text-2xl font-bold mb-4">暫停選單</h2>

          <button @click="resume"
                  class="w-full py-2 bg-green-600 rounded-lg hover:bg-green-500">
            ➤ 繼續冒險
          </button>

          <button @click="openBag"
                  class="w-full py-2 bg-blue-600 rounded-lg hover:bg-blue-500">
            🎒 查看背包
          </button>

          <button @click="showConfirm = true"
                  class="w-full py-2 bg-red-600 rounded-lg hover:bg-red-500">
            ✖ 放棄戰鬥
          </button>

        </div>
      </div>

      <!-- 確認視窗 -->
      <div
        class="fixed inset-0 bg-black/70 flex justify-center items-center z-50 transition duration-300"
        :class="showConfirm ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'"
      >
        <div class="bg-gray-800 text-white w-72 p-5 rounded-xl shadow-xl space-y-4">

          <h2 class="text-center text-xl font-bold">確定放棄戰鬥？</h2>

          <button @click="confirmGiveUp"
                  class="w-full py-2 bg-red-600 rounded-lg hover:bg-red-500">
            ✔ 是的，我要放棄
          </button>

          <button @click="showConfirm = false"
                  class="w-full py-2 bg-gray-600 rounded-lg hover:bg-gray-500">
            返回
          </button>
        </div>
      </div>
    </div>

    <!-- 背包視窗 -->
    <div
      class="fixed inset-0 bg-black/60 flex justify-center items-center z-50 transition duration-300"
      :class="showBag ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'"
      >
      <div class="bg-gray-900/95 text-white w-[1000px] h-[900px] p-6 rounded-xl shadow-xl space-y-4 overflow-y-auto">
        <h2 class="text-center text-2xl font-bold mb-4">🎒 背包</h2>

        <!-- 分頁按鈕 -->
        <div class="flex justify-center gap-2 mb-4">
          <button @click="bagTab = 'items'"
                  :class="bagTab==='items' ? 'bg-yellow-600' : 'bg-gray-700'"
                  class="px-4 py-2 rounded-lg">道具</button>
          <button @click="bagTab = 'equips'"
                  :class="bagTab==='equips' ? 'bg-yellow-600' : 'bg-gray-700'"
                  class="px-4 py-2 rounded-lg">裝備</button>
          <button @click="bagTab = 'cards'"
                  :class="bagTab==='cards' ? 'bg-yellow-600' : 'bg-gray-700'"
                  class="px-4 py-2 rounded-lg">卡牌</button>
        </div>

        <!-- 道具列表 -->
       <div v-if="bagTab === 'items'" class="grid grid-cols-5 gap-4 p-4">
  
          <template v-if="playerPotions.length > 0">
            <div
              v-for="item in playerPotions" 
              :key="item.id" 
              class="flex justify-center relative"
            >
              <Item
                :item="item"
                :count="item.count"
                @use="useItem(0, item.id)"
              />
            </div>
          </template>

          <template v-else>
            <div class="col-span-5 text-center text-gray-400 text-lg">
              背包空的
            </div>
          </template>
          
        </div>

        <!-- 裝備列表 -->
        <div v-if="bagTab === 'equips'" class="grid grid-cols-5 gap-4 p-4">
      
          <template v-if="playerEquipments.length > 0">
            <div
              v-for="equip in playerEquipments" 
              :key="equip.id" 
              class="flex justify-center relative"
            >
              <Equip :equip="equip" />
              
              <div v-if="equip.count > 1" class="absolute bottom-[-20px] text-white font-bold">
                  x {{ equip.count }}
              </div>
            </div>
          </template>

          <template v-else>
            <div class="col-span-5 text-center text-gray-400 text-lg">
              沒有裝備
            </div>
          </template>

        </div>

        <!-- 卡牌列表 -->
        <div v-if="bagTab === 'cards'" class="grid grid-cols-5 gap-4">
          <template v-if="player.baseDeck.length > 0">
            <div 
              v-for="(card, index) in player.baseDeck" 
              :key="index" 
              class="flex flex-col items-center"
            >
              <template v-if="card">
                <GameCard :card="card" />
              </template>
              
              <template v-else>
                <div class="text-sm text-gray-400 p-2">資料讀取錯誤</div>
              </template>
            </div>
          </template>
          
          <template v-else>
            <div class="col-span-8 text-center text-gray-400 text-lg">
              卡組是空的
            </div>
          </template>
        </div>

        <button @click="showBag = false"
                class="absolute bottom-10 left-1/2 -translate-x-1/2 px-10 py-3 bg-yellow-600 rounded-xl hover:bg-yellow-500 text-lg font-bold shadow-lg"
        >
          關閉背包
        </button>
      </div>
    </div>

    <!-- 商店視窗 -->
    <GameShop
    ref="shopRef"
    :player="player"
    :potions="potions"
    :items="items"
    :cards="cards"
    :equipments="equipments" 
    :showshop="showShop"
    @close-shop="closeShop"
    @buy-card="handleBuyCard"
    @buy-potion="handleBuyPotion"
    @buy-equip="handleBuyEquip"
    />

    <!-- 選擇事件視窗 -->
    <ExpeditionEvent
    v-if="showEvent"
    :events="expeditionEvents"
    @choose="handleEventCoice"
    />
  </div>
</template>

<script>
import { cards } from '../src/js/data/card.js'
import { equipments, items, potions } from '../src/js/data/items.js'
import { player, warrior, mage, archer } from '../src/js/systems/player.js'
import { enemy } from '../src/js/data/enemies.js'
import { initBattle, generateRewards, chooseReward, drinkPowerPotion, finishGameCount, selectEvent} from '../src/js/systems/utils.js'
import { playCard, endPlayerTurn } from '../src/js/systems/battle.js'
import { expeditionEvents} from '../src/js/data/expeditionEvents.js'
import { applyRelicEffect } from '../src/js/systems/relics.js'

import PlayerStats from './components/PlayerStats.vue'
import EnemyStats from './components/EnemyStats.vue'
import PlayerHand from './components/PlayerHand.vue'
import GameLog from './components/GameLog.vue'
import RewardSelector from './components/RewardSelector.vue'
import GameLobby from './components/GameLobby.vue'
import ChooseJob from './components/ChooseJob.vue'
import GameShop from './components/Shop.vue'
import ExpeditionEvent from './components/ExpeditionEvent.vue'
import GameCard from './components/Card.vue'
import Item from './components/Item.vue'
import Equip from './components/Equip.vue'

export default {
  name: 'App',
  components: { PlayerStats, EnemyStats, GameCard, PlayerHand, GameLog, RewardSelector, GameLobby, ChooseJob, GameShop, ExpeditionEvent, Item, Equip},
  data() {
    return {
      cards: cards,
      items: items,
      potions: potions,
      equipments: equipments,
      screen: 'start',
      player: player(),
      warrior: warrior(),
      mage: mage(),
      archer: archer(),
      enemy: enemy,
      currentEnemy: null,
      turn: 1,
      isPlayerTurn: true,
      gameLog: [],
      backpack: [],
      gameMessage: "",
      showRewardBox: false,
      generatedRewards: [],
      showPause: false,
      showConfirm: false,
      showBag: false,
      showShop: false,
      bagTab: 'items',
      showEvent: false,
      expeditionEvents: expeditionEvents,
      effects: [],
      isEnemyHit: false,
      isEnemyHeal: false,
      isEnemyArmor: false,
      isPlayerHit: false,
      isPlayerHeal: false,
      isPlayerArmor: false,
      currentFrame: null,
      isAttacking: false,
      attackFrames: 3,
      ishurt: false,
      hurtFrames: 2,
      frameRate: 80,
      isInitializing: false,
    }
  },
  computed: {
    deckCount() {
      return this.player.deck.length;
    },
    discardCount() {
      return this.player.discard.length;
    },
    backpackCounts() {
      const counts = {};
      for (const id of this.player.backpack) {
        counts[id] = (counts[id] || 0) + 1;
      }
      return counts;
    },
    playerPotions() {
    const list = [];
    const counts = {};
    
    for (const id of this.player.backpack) {
      counts[id] = (counts[id] || 0) + 1;
    }

    for (const id in counts) {
      if (this.potions[id]) {
        list.push({
          ...this.potions[id], 
          count: counts[id]  
        });
      }
    }
      return list;
    },
    playerEquipments() {
      const list = [];
      const counts = {};

      for (const id of this.player.backpack) {
        counts[id] = (counts[id] || 0) + 1;
      }

      for (const id in counts) {
        if (this.equipments[id]) { 
          list.push({
            ...this.equipments[id],
            count: counts[id]
          });
        }
      }
      return list;
    },
    playerCombatImg() {
      const map = {
        warrior: require('./assets/images/job/warrior_idle_1.webp'),
        mage: require('./assets/images/job/mage.webp'),
        archer: require('./assets/images/job/archer.webp')
      };
      return map[this.player.job];
    },
    displayImage() {
      // 1. 優先判斷是否正在播放「受傷序列幀」
      if (this.ishurt) {
        return this.currentFrame;
      }

      // 3. 攻擊動畫
      if (this.isAttacking) {
        return this.currentFrame;
      }

      // 4. 平常狀態
      return this.playerCombatImg;
    },
  },
  methods: {
    startGame() {
      if (!this.player.name.trim()) {
        alert('請輸入名字！')
        return
      }
      this.screen = 'choose-job'
    },
    async endTurn() {
      this.isPlayerTurn = false;
      await endPlayerTurn(this.player, this.currentEnemy, this.addLogMessage, this.triggerEffect)
      this.turn++
      this.isPlayerTurn = true;
    },
    togglePause() {
      this.showPause = true;
    },
    resume() {
      this.showPause = false;
    },
    giveUp() {
      this.showConfirm = true;
    },
    confirmGiveUp() {
      this.showConfirm = false;
      this.showPause = false;
      this.screen = 'lobby';
      finishGameCount(this.player);
    },
    openBag() {
      this.showBag = true;
    },
    useItem(index, itemId) {
      const itemIndex = this.player.backpack.findIndex(i => i === itemId);
      if (itemIndex === -1) return;

      const item = this.potions[itemId];

      // 治療藥水可以重複使用
      if (item.id === 'heal_potion') {
        this.player.hp = Math.min(this.player.maxHP, this.player.hp + item.heal);
        alert(`${item.name} 已使用，回復 ${item.heal} HP！`);

        // 使用後刪掉該物品
        this.player.backpack.splice(itemIndex, 1);
        return;
      }

      // 強力藥水判斷是否已有同類效果
      if (item.id.includes('power_potion')) {
        if (this.player.activePotions?.some(p => p.type === 'power')) {
          alert(`已有強力藥水效果，無法再次使用！`);
          return;
        }

        drinkPowerPotion(this.player, item);
        alert(`${item.name} 已使用，增加 ${item.power} 攻擊力`);

        // 記錄正在使用的強力藥水
        if (!this.player.activePotions) this.player.activePotions = [];
        this.player.activePotions.push({ type: 'power', grade: item.grade });

        // 使用後刪掉該物品
        this.player.backpack.splice(itemIndex, 1);
        return;
      }
    },
    addLogMessage(message) {
      const timestamp = new Date().toLocaleTimeString('zh-TW', { hour: '2-digit', minute: '2-digit', second: '2-digit' })
      this.gameLog.push(`[${timestamp}] ${message}`)
    }, 
    showMessage(message) {
      this.gameMessage = message;
      setTimeout(() => {
        this.gameMessage = "";
      }, 1200);
    },
    spawnRewards() {
      this.generatedRewards = generateRewards(this.player, 3);
      this.showRewardBox = true;
    },
    applyReward(reward) {
      chooseReward(this.player, reward);
    },
    hideRewards() {
      this.showRewardBox = false;
      this.generatedRewards = [];
      this.screen = 'lobby';
      finishGameCount(this.player);
      if (this.$refs.shopRef) {
        this.$refs.shopRef.generateShopItems();
      }
    },
    selectJob(job) {
      this.player.job = job;
      this.screen = "lobby";
    },
    initCard() {
      let deckIds = [];

      switch (this.player.job) {
        case "warrior":
          deckIds = this.warrior.baseDeck;
          this.player.maxHP = this.warrior.maxHP;
          this.player.hp = this.warrior.hp;
          this.player.ap = this.warrior.ap;
          this.player.mp = this.warrior.mp;
          break;
        case "mage":
          deckIds = this.mage.baseDeck;
          this.player.maxHP = this.mage.maxHP;
          this.player.hp = this.mage.hp;
          this.player.ap = this.mage.ap;
          this.player.mp = this.mage.mp;
          break;
        case "archer":
          deckIds = this.archer.baseDeck;
          this.player.maxHP = this.archer.maxHP;
          this.player.hp = this.archer.hp;
          this.player.ap = this.archer.ap;
          this.player.mp = this.archer.mp;
      }
      this.player.baseDeck = deckIds
      .map(id => this.createCardInstance(id))
      .filter(card => card !== null); 
    },
    openShop() {
      this.showShop = true;
    },
    closeShop() {
      this.showShop = false;
    },
    handleBuyCard(cardId, price, cardsForSale) {
      const index = cardsForSale.findIndex(c => c.id === cardId);
      if(this.player.coin >= price) {
        this.player.coin -= price;

        const newCard = this.createCardInstance(cardId);
        if (newCard) {
          this.player.baseDeck.push(newCard);
        }
        if (index != -1) {
          cardsForSale.splice(index, 1);
        }
        this.showMessage("購買成功");
      }
      else {
        this.showMessage("金幣不足");
      }
    },
    handleBuyEquip(equipId, index, equipsForSale) {
      if(this.player.coin >= equipId.price) {
      this.player.coin -= equipId.price;

      this.player.backpack.push(equipId.id); 

      if (index !== -1) {
        equipsForSale.splice(index, 1);
      }

        this.showMessage("購買成功");
      }
      else {
        this.showMessage("金幣不足");
      }
    },
    handleBuyPotion(potionId, price, potionsForSale) {
      const index = potionsForSale.findIndex(c => c.id === potionId);
      if(this.player.coin >= price) {
        this.player.coin -= price;
        this.player.backpack.push(potionId);
        if (index != -1) {
          potionsForSale.splice(index, 1);
        }
        this.showMessage("購買成功");
      }
      else {
        this.showMessage("金幣不足");
      }
    },
    startExpedition() {
      this.showEvent = true;
    },
    handleEventCoice(event) {
      const enemyData = selectEvent(event, this.enemy);
      this.currentEnemy = enemyData;
      this.showEvent = false;
      this.enterGame();
    },
    createCardInstance(cardId) {
      const allCards = { 
        ...this.cards.common, 
        ...this.cards[this.player.job] 
      };
      const originalCard = allCards[cardId];
      if (!originalCard) return null;

      return {
        ...originalCard,
        uid: `${cardId}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        costAP: originalCard.costAP,
        costMP: originalCard.costMP
      };
    },
    triggerEffect(target, type, value) {
      const id = Date.now() + Math.random();
      const isEnemy = target === this.currentEnemy;

      // === 敵人特效判斷 ===
      if (isEnemy) {
        if (type === 'damage' || type === 'break') {
          this.isEnemyHit = true;
          setTimeout(() => { this.isEnemyHit = false; }, 600);
        }
        if (type === 'heal') {
          this.isEnemyHeal = true;
          setTimeout(() => { this.isEnemyHeal = false; }, 600);
        }
        if (type === 'armor') {
          this.isEnemyArmor = true;
          setTimeout(() => { this.isEnemyArmor = false; }, 600);
        }
      }

      // === 玩家特效判斷 ===
      if (!isEnemy) {
        if (type === 'damage' || type === 'break') {
          this.isPlayerHit = true;
          setTimeout(() => { this.isPlayerHit = false; }, 600);
        }
        if (type === 'heal') {
          this.isPlayerHeal = true;
          setTimeout(() => { this.isPlayerHeal = false; }, 600);
        }
        if (type === 'armor') {
          this.isPlayerArmor = true;
          setTimeout(() => { this.isPlayerArmor = false; }, 600);
        }
      }
      const baseX = isEnemy ? 75 : 25;
      const baseY = 40;

      const sideCondition = isEnemy ? (e => e.x > 50) : (e => e.x <= 50);
      const activeCount = this.effects.filter(sideCondition).length;

      const yOffset = activeCount * 2; 
      
      const xOffset = (activeCount % 2 === 0 ? 1 : -1) * (activeCount * 1.5);

      const randomX = (Math.random() - 0.5) * 2;
      const randomY = (Math.random() - 0.5) * 2;

      const effect = {
        id,
        type,
        value,
        x: baseX + xOffset + randomX,
        y: baseY + yOffset + randomY  
      };

      this.effects.push(effect);

      setTimeout(() => {
        this.effects = this.effects.filter(e => e.id !== id);
      }, 2000);
    },
    getEffectClass(type) {
      switch(type) {
        case 'damage': return 'text-red-500 text-6xl';
        case 'armor': return 'text-blue-400 text-4xl';
        case 'break': return 'text-yellow-400 text-5xl';
        case 'heal': return 'text-green-400 text-4xl';

        case 'burn':   return 'text-orange-500 text-5xl';  
        case 'freeze': return 'text-cyan-400 text-5xl';   
        case 'poison': return 'text-purple-500 text-5xl'; 

        default: return 'text-white';
      }
    },
    enterGame() {
      this.isInitializing = true;
      this.screen = 'battle';
      this.gameLog = [];
      
      // 初始化戰鬥狀態
      this.turn = 1;
      this.isPlayerTurn = true;
      this.ishurt = false;
      
      // === 初始化遺物相關狀態 ===
      this.tookDamageThisRound = false; 
      if (this.player) {
        this.player.lifeHeartTriggered = false; // 重置生命之心
      }

      initBattle(this.player, this.currentEnemy);

      this.$nextTick(() => {
        this.isInitializing = false;
      });

      this.addLogMessage("系統: 遊戲啟動，戰鬥開始！");
      this.addLogMessage("玩家回合開始");

      // 檢查第一回合的遺物 (如森林古盾)
      this.handleTurnStartRelics();
    },
    // 用來觸發「回合開始」類的遺物
    handleTurnStartRelics() {
      applyRelicEffect(this.player, 'onTurnStart', {
        turn: this.turn,
        tookDamageThisRound: this.tookDamageThisRound, // 給翠綠輪環用
        addLog: this.addLogMessage,
        triggerEffect: this.triggerEffect
      });

      // 結算完遺物後，重置受傷狀態，準備迎接新的一輪
      this.tookDamageThisRound = false; 
    },
    async playAttackAnimation(job) {
      this.isAttacking = true;
      for (let i = 1; i <= this.attackFrames; i++) {
        try {
          // 這樣 Webpack 才能找到 ./assets/images/ani/ 資料夾
          this.currentFrame = require(`./assets/images/job/${job}_atk_${i}.webp`);
        } catch (e) {
          console.error(`找不到動畫幀: ${job}_atk_${i}.webp`, e);
        }
        // 確保這裡使用的是 this.frameRate (與 data 一致)
        await new Promise(resolve => setTimeout(resolve, this.frameRate));
      }
      this.isAttacking = false;
      this.currentFrame = null;
    },
    async playhurtAnimation(job) {
      this.ishurt = true;
      for (let i = 1; i <= this.hurtFrames; i++) {
        try {
          // 確保路徑與資料夾結構一致，例如 warrior_hurt_1.webp
          this.currentFrame = require(`./assets/images/job/${job}_hurt_${i}.webp`);
        } catch (e) {
          console.error(`找不到動畫幀: ${job}_hurt_${i}.webp`, e);
        }
        await new Promise(resolve => setTimeout(resolve, this.frameRate));
      }
      this.ishurt = false;
      this.currentFrame = null;
    },
    // 修改原有的點擊卡牌逻辑
    async clickCard(card) {
      if(card.type.includes('atk')) {
        // 1. 先播放動畫
        await this.playAttackAnimation(this.player.job);
      }
      
      // 2. 接著執行原有的出牌效果
      playCard(this.player, this.currentEnemy, card, this.addLogMessage, this.showMessage, this.triggerEffect);
    }
  },
 watch: {
    // 監聽玩家回合 -> 觸發回合開始特效
    isPlayerTurn(isTurn) {
      if (isTurn) {
        this.handleTurnStartRelics();
      }
    },

    // 監聽怪物死亡
    'currentEnemy.hp'(newHp) {
      if (newHp <= 0) {
        console.log('怪物死亡！');
        this.spawnRewards();
      }
    },

    // 監聽玩家血量 -> 1. 判死 2. 記錄受傷 3. 觸發血量變化特效(生命之心)
    'player.hp'(newHp, oldHp) {
      // 1. 死亡判定
      if (newHp <= 0) {
        console.log('玩家死亡！');
        this.showMessage('你死了！');
        setTimeout(() => {
          this.screen = 'start';
        }, 1200);
        return;
      }

      // 2. 記錄受傷 (修正點：確保是在戰鬥畫面且 oldHp 有值時才播放)
      if (!this.isInitializing &&oldHp !== undefined && newHp < oldHp && this.screen === 'battle') {
        this.tookDamageThisRound = true;
        this.playhurtAnimation(this.player.job);
      }

      // 3. 觸發「血量變化」類的遺物 (如生命之心)
      applyRelicEffect(this.player, 'onHpChange', {
        newHp: newHp,
        oldHp: oldHp,
        addLog: this.addLogMessage,
        triggerEffect: this.triggerEffect
      });
    }
  }
}
</script>

