<template>
  <div class="relative w-full h-full text-white">

    <!-- 左上角 玩家資訊 -->
    <div class="absolute top-4 left-2 bg-black/60 p-3 rounded-xl flex gap-3 items-center shadow-lg">
      <div class="w-[100px] h-[100px] rounded-full overflow-hidden border border-gray-300">
        <img :src="jobAvatar" class="w-full h-full object-cover scale-[1.6]" />
      </div>
      <div>
        <div class="text-sm">冒險者：{{ player.name }}</div>
        <div class="text-sm flex flex-col gap-1">
          <span>❤️ 血量：{{ player.hp }}/{{ player.maxHP }}</span> 
          <span>🛡 護甲：{{ player.defend }}</span> 
          <span>👊 攻擊力：{{ player.attack }}</span> 
          <span>🪙 金幣：{{ player.coin }}</span> 
        </div>
      </div>
    </div>

    <!-- 中間角色展示框 -->
    <div class="absolute top-28 left-1/2 transform -translate-x-1/2 
                bg-black/70 p-6 rounded-xl w-[650px] shadow-xl">
      
      <div class="text-center text-2xl font-bold mb-4">
        歡迎來到Danjoun
      </div>

      <!-- 職業角色大圖 -->
      <div class="w-[600px] h-[400px] rounded-xl overflow-hidden border border-gray-400 shadow-lg">
        <img :src="jobImage" class="w-full h-full object-cover" :class="selectJob === 'mage' ? 'scale-[1.6]' : 'scale-[1]'" />
      </div>
    </div>

    <!-- 功能按鈕 3顆 -->
    <div class="absolute bottom-[-720px] left-1/2 transform -translate-x-1/2 flex gap-6">

      <button class="lobby-btn" @click="$emit('shop')">🏪<br/>商店</button>

      <button class="lobby-btn" @click="$emit('backpack')">🎒<br/>背包</button>

      <button class="lobby-btn" @click="$emit('start-adventure')">🚀<br/>遠征</button>

    </div>
  </div>
</template>

<script>
export default {
  name: "GameLobby",
  props: {
    player: Object,
    warrior: Object,
    mage: Object,
    selectJob: String,
    card: Object
  },
  computed: {
    jobImage() {
      const map = {
        warrior: new URL('@/assets/images/job/warrior-cover.webp', import.meta.url).href,
        mage: new URL('@/assets/images/job/mage-cover.webp', import.meta.url).href,
        archer: new URL('@/assets/images/job/archer-cover.webp', import.meta.url).href
      };

      return map[this.selectJob];
    },
    jobAvatar() {
      const map = {
        warrior:new URL('@/assets/images/job/warrior-medal.webp', import.meta.url).href,
        mage: new URL('@/assets/images/job/mage-medal.webp', import.meta.url).href,
        archer: new URL('@/assets/images/job/archer-medal.webp',import.meta.url).href
      };

      return map[this.selectJob];
      }
  }
}
</script>

<style scoped>
.lobby-btn {
  width: 200px;
  height: 100px;
  background-image: url();
  background-size: cover;
  background-position: center;
  border: 2px solid #444;
  border-radius: 15px;
  text-align: center;
  padding-top: 8px;
  font-size: 14px;
  line-height: 16px;
  transition: 0.2s;
}
.lobby-btn:hover {
  background: #363636;
  transform: translateY(-4px);
}
</style>
